package com.notificationservice.infrastructure.persistence.repository;import com.notificationservice.infrastructure.persistence.entity.NotificationEntity;import org.springframework.data.domain.Pageable;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;import java.time.Instant;import java.util.*;public interface JpaNotificationRepository extends JpaRepository<NotificationEntity,UUID>{List<NotificationEntity> findByUserIdOrderByCreatedAtDesc(UUID id,Pageable p);long countByUserIdAndReadFalse(UUID id);@Modifying@Query("update NotificationEntity n set n.read=true,n.readAt=:at where n.userId=:id and n.read=false")int markAll(@Param("id")UUID id,@Param("at")Instant at);}
